sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var parsedAttachment = current.getValue('u_parsed_attachment_sys_id') || '';
    var embeddedAttachment = current.getValue('u_embedded_attachment_sys_id') || '';

    if (!parsedAttachment || parsedAttachment == embeddedAttachment)
        return;

    var service = new x_2311790_skills_0.EmbeddingService();
    var result = service.prepareProfile(current);

    if (!result.ok) {
        var error = (result.errorCode || 'UNKNOWN_EMBEDDING_FAILURE') + ': ' + (result.errorMessage || 'Embedding failed.');
        if (error.length > 997)
            error = error.substring(0, 997) + '...';
        current.setValue('u_embedding_error', error);
        return;
    }

    current.setValue('embedding', result.vector);
    current.setValue('u_embedding_model', result.model || '');
    current.setValue('u_embedding_version', result.version || '');
    current.setValue('u_embedding_dim', result.dim || 0);
    current.setValue('u_embedded_at', gs.nowDateTime());
    current.setValue('u_embedded_attachment_sys_id', parsedAttachment);
    current.setValue('u_embedding_error', '');
})(current, previous);
